const response = $input.first().json;
const products = response.products || [];
const stats = response.stats || {};

const validProducts = [];
for (const p of products) {
  if (!p.product_name || !p.lender_name || !p.source_url) {
    continue;
  }
  if (p.interest_rate_min !== null && p.interest_rate_min !== undefined) {
    const r = Number(p.interest_rate_min);
    if (r < 0 || r > 100) continue;
  }
  if (p.interest_rate_max !== null && p.interest_rate_max !== undefined) {
    const r = Number(p.interest_rate_max);
    if (r < 0 || r > 100) continue;
  }
  validProducts.push(p);
}

const rawJson = JSON.stringify(validProducts);
const sqlEscapedJson = rawJson.replace(/'/g, "''");

return [{
  json: {
    validProducts,
    count: validProducts.length,
    stats,
    productsJson: rawJson,
    sqlEscapedJson: sqlEscapedJson
  }
}];

const prev = $('Validate & Clean Products').first().json;
return [{
  json: {
    status: 'success',
    products_upserted: prev.count,
    crawl_stats: prev.stats,
    timestamp: new Date().toISOString()
  }
}];

const prev = $('Validate & Clean Products').first().json;
return [{
  json: {
    status: 'fallback_kept',
    message: 'No new valid products extracted; seed products preserved',
    crawl_stats: prev.stats,
    timestamp: new Date().toISOString()
  }
}];
